// Business Charts v7: single `context` arg. Bare `data`/`theme` are not in scope.
const data = context.panel.data;
const theme = context.grafana.theme;
const c = (theme && theme.colors) ? theme.colors : null;
const dark = theme ? theme.isDark : true;

const ink   = c ? c.text.primary   : (dark ? '#f2f3f5' : '#16161a');
const ink2  = c ? c.text.secondary : (dark ? '#9a9ea6' : '#6b6f76');
const grid  = c ? c.border.weak    : (dark ? '#2a2d33' : '#e5e7eb');
const panel = c ? c.background.secondary : (dark ? '#1a1c1f' : '#ffffff');
const edge  = c ? c.border.medium  : (dark ? '#33363b' : '#d6d9de');

// Validated categorical palette (dataviz skill, dark surface). Past eight exercises the hues
// repeat; the legend and tooltip carry identity from there, never colour alone.
const PALETTE = ['#3987e5','#d95926','#199e70','#c98500','#d55181','#008300','#9085e9','#e66767'];

const arr = (f) => (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []);
const key = (d) => d.getFullYear() + '-' +
  String(d.getMonth() + 1).padStart(2, '0') + '-' +
  String(d.getDate()).padStart(2, '0');

const nameOf = (frame) => {
  const vf = frame.fields && frame.fields.find((f) => f.type === 'number');
  return String(frame.name
    || (vf && vf.labels && vf.labels.__name__)
    || (vf && vf.config && vf.config.displayNameFromDS)
    || '');
};

const all = (data.series || []).filter((f) => f && f.fields && f.fields.length);

// Tombstones. The store only appends and its delete API is not exposed, so a removed set is
// recorded as a `<exercise>_deleted` sample at that set's own timestamp. Every reader replays
// the same rule or the chart keeps showing work that was taken back; the app does this in
// reconstruct() and this is the same logic for the panel.
const voided = new Set();
all.forEach((frame) => {
  const raw = nameOf(frame);
  if (!/_deleted$/.test(raw)) { return; }
  const prefix = raw.replace(/^health_/, '').replace(/_deleted$/, '');
  const tf = frame.fields.find((f) => f.type === 'time');
  arr(tf).forEach((t) => voided.add(prefix + '@' + t));
});

const series = all.filter((f) => !/_deleted$/.test(nameOf(f)));
if (!series.length) { return {}; }

// Sum each series into LOCAL calendar days. Doing it here rather than in MetricsQL is the
// whole point: a PromQL step aligns to Unix epoch multiples, so a 1d bucket lands on UTC
// midnight and an evening session drifts into the next day.
const byName = new Map();
const allDays = new Set();

series.forEach((frame) => {
  const tf = frame.fields.find((f) => f.type === 'time');
  const vf = frame.fields.find((f) => f.type === 'number');
  if (!tf || !vf) { return; }

  const raw = nameOf(frame);
  const prefix = raw.replace(/^health_/, '').replace(/_volume$/, '');
  const name = prefix.replace(/_/g, ' ');

  const ts = arr(tf), vs = arr(vf);
  const days = byName.get(name) || new Map();
  for (let i = 0; i < ts.length; i++) {
    const v = vs[i];
    if (v === null || v === undefined || Number.isNaN(v) || v === 0) { continue; }
    if (voided.has(prefix + '@' + ts[i])) { continue; }   // retracted by a tombstone
    const k = key(new Date(ts[i]));
    days.set(k, (days.get(k) || 0) + v);
    allDays.add(k);
  }
  if (days.size) { byName.set(name, days); }
});

if (!byName.size) { return {}; }

const days = Array.from(allDays).sort();
const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const labels = days.map((d) => { const p = d.split('-').map(Number); return MON[p[1] - 1] + ' ' + p[2]; });

const names = Array.from(byName.keys()).sort();
const lines = names.map((name, i) => {
  const colour = PALETTE[i % PALETTE.length];
  return {
    name: name,
    type: 'line',
    connectNulls: true,
    data: days.map((d) => {
      const v = byName.get(name).get(d);
      return (v === undefined) ? null : Math.round(v * 100) / 100;
    }),
    symbol: 'circle',
    symbolSize: 7,
    smooth: 0.15,
    lineStyle: { width: 2, color: colour },
    itemStyle: { color: colour, borderWidth: 2, borderColor: panel }
  };
});

if (lines.length === 1) {
  lines[0].areaStyle = { color: { type: 'linear', x: 0, y: 0, x2: 0, y2: 1, colorStops: [
    { offset: 0, color: 'rgba(57,135,229,0.55)' },
    { offset: 0.5, color: 'rgba(57,135,229,0.22)' },
    { offset: 1, color: 'rgba(57,135,229,0.02)' }
  ] } };
}

return {
  animationDuration: 250,
  animationDurationUpdate: 250,
  animationEasing: 'cubicOut',
  animationEasingUpdate: 'cubicOut',
  grid: { left: 64, right: 20, top: 22, bottom: 58 },
  tooltip: {
    trigger: 'axis',
    // Themed explicitly: ECharts defaults to a white card, unreadable on a dark dashboard.
    backgroundColor: panel,
    borderColor: edge,
    borderWidth: 1,
    padding: [8, 10],
    textStyle: { color: ink, fontSize: 12 },
    extraCssText: 'border-radius:8px; box-shadow:0 6px 20px rgba(0,0,0,.28);',
    axisPointer: { type: 'line', lineStyle: { color: ink2, width: 1, type: 'dashed' } },
    order: 'valueDesc',
    valueFormatter: (v) => (v === null || v === undefined) ? '' : Math.round(v).toLocaleString() + ' kg'
  },
  legend: {
    bottom: 0, textStyle: { color: ink2 }, icon: 'roundRect',
    itemWidth: 10, itemHeight: 10, data: names
  },
  xAxis: {
    type: 'category', data: labels, boundaryGap: false,
    axisLabel: { color: ink2 },
    axisLine: { lineStyle: { color: grid } },
    axisTick: { show: false }
  },
  yAxis: {
    type: 'value', scale: false, min: 0,
    axisLabel: { color: ink2, formatter: (v) => v >= 1000 ? (v / 1000) + 'k' : String(v) },
    splitLine: { lineStyle: { color: grid } }
  },
  series: lines
};

